import pandas as pd
import os
from pathlib import Path
from sklearn.metrics import confusion_matrix, classification_report

# --- DYNAMIC CONFIG (Finds the logs folder automatically) ---
BASE_DIR = Path(__file__).resolve().parent
LOGS_DIR = BASE_DIR / "logs"

def analyze_laptop(pc_name):
    print("=" * 60)
    print(f" LIVE METRICS REPORT FOR: {pc_name}")
    print("=" * 60)

    all_expected = []
    all_predicted = []
    files_found = 0

    # Read the three CSV files generated by run_tests.py
    for state in ["normal", "moderate", "high"]:
        file_path = LOGS_DIR / f"{pc_name}_{state}.csv"
        
        if not file_path.exists():
            print(f"⚠️ Missing file: {file_path}")
            continue
            
        files_found += 1
        df = pd.read_csv(file_path)
        
        # Extract expected and predicted (convert to uppercase to match)
        expected = df['expected'].str.upper().tolist()
        predicted = df['predicted'].str.upper().tolist()
        
        all_expected.extend(expected)
        all_predicted.extend(predicted)

        # Calculate False Alarms for NORMAL test
        if state == "normal":
            false_alarms = df[df['predicted'] != 'NORMAL']
            fa_rate = (len(false_alarms) / len(df)) * 100 if len(df) > 0 else 0
            print(f"\n[False Alarm Analysis - Normal Test]")
            print(f"  Total Normal Predictions: {len(df)}")
            print(f"  False Alarms (Predicted HIGH/MOD): {len(false_alarms)} ({fa_rate:.2f}%)")

        # Calculate Missed Alerts for HIGH test
        if state == "high":
            missed = df[df['predicted'] != 'HIGH']
            missed_rate = (len(missed) / len(df)) * 100 if len(df) > 0 else 0
            print(f"\n[Missed Alert Analysis - High Test]")
            print(f"  Total High Predictions: {len(df)}")
            print(f"  Missed Alerts (Predicted Normal/Mod): {len(missed)} ({missed_rate:.2f}%)")

    if files_found == 0:
        print("\n❌ ERROR: No log files found. Check the PC name (case-sensitive).")
        print(f"Looked in: {LOGS_DIR}")
        return

    # --- PRINT CONFUSION MATRIX ---
    print("\n[Live Confusion Matrix]")
    labels = ["NORMAL", "MODERATE", "HIGH"]
    cm = confusion_matrix(all_expected, all_predicted, labels=labels)
    
    # Pretty print the matrix
    cm_df = pd.DataFrame(cm, index=[f"Actual {l}" for l in labels], columns=[f"Pred {l}" for l in labels])
    print(cm_df.to_string())
    
    print("\n[Classification Report]")
    print(classification_report(all_expected, all_predicted, labels=labels, zero_division=0))
    print("\n")

if __name__ == "__main__":
    # MUST MATCH THE EXACT FILE NAME IN THE LOGS FOLDER
    analyze_laptop("yoga lenovo")